import { create } from 'zustand';
import type {
  Conversation,
  ConversationStatus,
  SessionMode,
} from '@/types';
import { useSettingsStore } from '@/stores/settingsStore';
import { useUIStore } from '@/stores/uiStore';
import { useTeamStore } from '@/stores/teamStore';

const BASE_URL = 'http://127.0.0.1:8081';

/** Dedup: skip if same session was archived within cooldown window. */
const ARCHIVE_COOLDOWN_MS = 15 * 60 * 1000; // 15 minutes
const _recentArchives = new Map<string, number>();

/**
 * Archive a session's messages to memory daily log.
 * @param skipCooldown - bypass 15-min dedup (used before delete)
 * @returns true if archive succeeded or was skipped by cooldown, false on error
 */
function archiveSession(sessionId: string, skipCooldown = false): Promise<boolean> {
  if (!skipCooldown) {
    const now = Date.now();
    const last = _recentArchives.get(sessionId);
    if (last && now - last < ARCHIVE_COOLDOWN_MS) return Promise.resolve(true);
  }

  return fetch(`${BASE_URL}/v1/memory/archive`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ session_id: sessionId }),
  })
    .then((res) => {
      if (res.ok) {
        _recentArchives.set(sessionId, Date.now());
        return true;
      }
      return false;
    })
    .catch(() => false);
}

interface SessionState {
  sessions: Conversation[];
  currentSessionId: string | null;
  loading: boolean;
  /** Session IDs that completed while user was viewing another session */
  unseenCompletedSessions: Set<string>;

  loadSessions: (workingDir?: string) => Promise<void>;
  createSession: (title?: string, mode?: SessionMode) => string;
  switchSession: (id: string) => void;
  deleteSession: (id: string) => Promise<void>;
  renameSession: (id: string, title: string) => Promise<void>;
  pinSession: (id: string) => Promise<void>;
  unpinSession: (id: string) => Promise<void>;
  updateSessionStatus: (id: string, status: ConversationStatus) => void;
  markUnseenCompletion: (id: string) => void;
  clearUnseenCompletion: (id: string) => void;
  saveSession: (
    id: string,
    messages: unknown[],
    metadata?: Record<string, unknown>,
  ) => Promise<boolean>;
  updateSessionMetadata: (
    id: string,
    metadata: Record<string, unknown>,
  ) => Promise<boolean>;
  getSession: (id: string) => Conversation | undefined;
}

export const useSessionStore = create<SessionState>((set, get) => ({
  sessions: [],
  currentSessionId: null,
  loading: false,
  unseenCompletedSessions: new Set<string>(),

  loadSessions: async (workingDir?: string) => {
    set({ loading: true });
    const maxAttempts = 30;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        // Health check first
        const healthRes = await fetch(`${BASE_URL}/health`);
        if (!healthRes.ok) throw new Error('Server not healthy');

        const url = workingDir
          ? `${BASE_URL}/v1/sessions?working_dir=${encodeURIComponent(workingDir)}`
          : `${BASE_URL}/v1/sessions`;

        const response = await fetch(url);
        if (!response.ok) throw new Error(`Sessions API returned ${response.status}`);

        const data = await response.json();
        const rawSessions = data.sessions || [];

        const sessions: Conversation[] = rawSessions
          .map((s: Record<string, unknown>) => {
            const meta = (s.metadata || {}) as Record<string, unknown>;
            const createdAt =
              (meta.createdAt as number) ||
              (s.createdAt as number) ||
              (s.modified ? new Date(s.modified as string).getTime() : Date.now());
            const updatedAt = s.modified
              ? new Date(s.modified as string).getTime()
              : createdAt;

            return {
              id: (s.session_id || s.id) as string,
              title: (meta.title || s.title || 'Untitled') as string,
              createdAt,
              updatedAt,
              status: 'idle' as ConversationStatus,
              workingDir: (meta.workingDir || meta.working_dir || s.workingDir || s.working_dir || '') as string,
              isCustomTitle: (meta.isCustomTitle || false) as boolean,
              mode: ((meta.session_mode || s.session_mode || 'general') as SessionMode),
              pinned: Boolean(meta.pinned ?? s.pinned),
              pinnedAt: (() => {
                const v = meta.pinnedAt ?? meta.pinned_at ?? s.pinnedAt ?? s.pinned_at;
                return typeof v === 'number' ? v : undefined;
              })(),
              messages: [],
            };
          })
          .sort(
            (a: Conversation, b: Conversation) => b.updatedAt - a.updatedAt,
          );

        set({ sessions, loading: false });
        return;
      } catch (e) {
        console.warn(
          `[Sessions] Backend not ready (attempt ${attempt}/${maxAttempts}):`,
          (e as Error).message,
        );
        if (attempt < maxAttempts) {
          await new Promise((r) => setTimeout(r, 1000));
        }
      }
    }

    console.error('[Sessions] Failed to load sessions after all retries');
    set({ loading: false });
  },

  createSession: (title?: string, mode?: SessionMode) => {
    // Fire-and-forget: archive the old session's messages to memory/*.md
    const oldSessionId = get().currentSessionId;
    if (oldSessionId) {
      archiveSession(oldSessionId);
    }

    const defaultTitles: Record<string, string> = {
      general: 'New Chat',
      design: 'New Design',
      plan: 'New Plan',
      team: 'Team Chat',
      meeting: 'Meeting Notes',
      recording: 'Screen Recording',
    };
    const sessionMode = mode || 'general';
    const sessionTitle = title || defaultTitles[sessionMode] || 'New Chat';

    // Use unique ID with random suffix to avoid collisions (matches legacy)
    const id =
      Date.now().toString() +
      '-' +
      Math.random().toString(36).substring(2, 11);
    // Use default working folder for new sessions
    const settings = useSettingsStore.getState();
    const defaultDir = settings.defaultWorkingFolder || settings.workingDir || '';
    const session: Conversation = {
      id,
      title: sessionTitle,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      status: 'idle',
      workingDir: defaultDir,
      isCustomTitle: !!title,
      mode: sessionMode,
      messages: [],
    };

    set((state) => ({
      sessions: [session, ...state.sessions],
      currentSessionId: id,
    }));

    // Persist initial metadata to backend
    fetch(`${BASE_URL}/v1/sessions/${id}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        messages: [],
        metadata: {
          title: sessionTitle,
          session_mode: sessionMode,
          createdAt: Date.now(),
          workingDir: defaultDir,
          isCustomTitle: !!title,
        },
      }),
    }).catch(() => {});

    // Sync working dir to backend so tools use the correct directory
    if (defaultDir) {
      useSettingsStore.getState().setWorkingDir(defaultDir);
    }

    return id;
  },

  switchSession: (id: string) => {
    // Archive the session we're leaving (fire-and-forget, 15-min debounce)
    const oldSessionId = get().currentSessionId;
    if (oldSessionId && oldSessionId !== id) {
      archiveSession(oldSessionId);
    }

    // Clear unseen completion flag when user views this session
    const unseen = get().unseenCompletedSessions;
    if (unseen.has(id)) {
      const next = new Set(unseen);
      next.delete(id);
      set({ currentSessionId: id, unseenCompletedSessions: next });
    } else {
      set({ currentSessionId: id });
    }

    // Sync the session's working directory to the backend
    const session = get().sessions.find((s) => s.id === id);
    const dir = session?.workingDir || useSettingsStore.getState().workingDir || '';
    if (dir) {
      fetch(`${BASE_URL}/v1/config/working-dir`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ working_dir: dir }),
      }).catch(() => {});
    }

    // Sync team panel with the new session
    const teamIdForSession = useUIStore.getState().getSessionTeam(id);
    const currentTeamId = useTeamStore.getState().activeTeamId;
    if (teamIdForSession && teamIdForSession !== currentTeamId) {
      useTeamStore.getState().loadTeamFromAPI(teamIdForSession);
    } else if (!teamIdForSession && currentTeamId) {
      useTeamStore.getState().resetTeam();
    }
  },

  deleteSession: async (id: string) => {
    // Archive to memory/*.md before deleting — skip cooldown and check result
    const archived = await archiveSession(id, true);
    if (!archived) {
      console.warn(`[Sessions] Archive failed for ${id}, proceeding with delete anyway`);
      // Still delete — archive failure shouldn't block UX permanently,
      // but log so we know data may have been lost.
    }

    try {
      const response = await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        console.error('Failed to delete session:', response.status);
      }
    } catch (e) {
      console.error('SessionAPI.delete error:', e);
    }

    set((state) => {
      const sessions = state.sessions.filter((s) => s.id !== id);
      let currentSessionId = state.currentSessionId;

      if (state.currentSessionId === id) {
        if (sessions.length > 0) {
          currentSessionId = sessions[0].id;
        } else {
          // Legacy behavior: create a new session when deleting the last one
          const newId =
            Date.now().toString() +
            '-' +
            Math.random().toString(36).substring(2, 11);
          const newSession: Conversation = {
            id: newId,
            title: 'New Chat',
            createdAt: Date.now(),
            updatedAt: Date.now(),
            status: 'idle',
            workingDir: '',
            isCustomTitle: false,
            mode: 'general',
            messages: [],
          };
          sessions.push(newSession);
          currentSessionId = newId;
        }
      }

      return { sessions, currentSessionId };
    });
  },

  renameSession: async (id: string, title: string) => {
    // Update local state immediately
    set((state) => ({
      sessions: state.sessions.map((s) =>
        s.id === id ? { ...s, title, isCustomTitle: true } : s,
      ),
    }));

    // Persist to backend
    try {
      await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ metadata: { title, isCustomTitle: true } }),
      });
    } catch (e) {
      console.error('SessionAPI.updateMetadata error:', e);
    }
  },

  pinSession: async (id: string) => {
    const now = Date.now();
    set((state) => ({
      sessions: state.sessions.map((s) =>
        s.id === id ? { ...s, pinned: true, pinnedAt: now } : s,
      ),
    }));
    try {
      await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ metadata: { pinned: true, pinnedAt: now } }),
      });
    } catch (e) {
      console.error('SessionAPI.pin error:', e);
    }
  },

  unpinSession: async (id: string) => {
    set((state) => ({
      sessions: state.sessions.map((s) =>
        s.id === id ? { ...s, pinned: false, pinnedAt: undefined } : s,
      ),
    }));
    try {
      await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ metadata: { pinned: false, pinnedAt: null } }),
      });
    } catch (e) {
      console.error('SessionAPI.unpin error:', e);
    }
  },

  updateSessionStatus: (id: string, status: ConversationStatus) => {
    set((state) => ({
      sessions: state.sessions.map((s) =>
        s.id === id ? { ...s, status, updatedAt: Date.now() } : s,
      ),
    }));
  },

  markUnseenCompletion: (id: string) => {
    set((state) => {
      const next = new Set(state.unseenCompletedSessions);
      next.add(id);
      return { unseenCompletedSessions: next };
    });
  },

  clearUnseenCompletion: (id: string) => {
    set((state) => {
      if (!state.unseenCompletedSessions.has(id)) return state;
      const next = new Set(state.unseenCompletedSessions);
      next.delete(id);
      return { unseenCompletedSessions: next };
    });
  },

  saveSession: async (
    id: string,
    messages: unknown[],
    metadata: Record<string, unknown> = {},
  ) => {
    try {
      const response = await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages, metadata }),
      });
      return response.ok;
    } catch (e) {
      console.error('SessionAPI.save error:', e);
      return false;
    }
  },

  updateSessionMetadata: async (
    id: string,
    metadata: Record<string, unknown>,
  ) => {
    try {
      const response = await fetch(`${BASE_URL}/v1/sessions/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ metadata }),
      });
      return response.ok;
    } catch (e) {
      console.error('SessionAPI.updateMetadata error:', e);
      return false;
    }
  },

  getSession: (id: string) => {
    return get().sessions.find((s) => s.id === id);
  },
}));

if (typeof window !== 'undefined') (window as any).__sessionStore = useSessionStore;
